DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.supply_edit_purchase(uuid,jsonb,jsonb,text)'::regprocedure) INTO definition;
definition:=replace(definition, 'IF qty IS NULL OR qty<=0 OR val IS NULL OR val<0 OR val::text IN(''NaN'',''Infinity'',''-Infinity'') THEN RAISE EXCEPTION ''Quantidade e valor inválidos''; END IF;'||chr(10)||' after_data', 'IF qty IS NULL OR qty<=0 OR val IS NULL OR val<0 OR val::text IN(''NaN'',''Infinity'',''-Infinity'') THEN RAISE EXCEPTION ''Quantidade e valor inválidos''; END IF;'||chr(10)||' IF o.status<>''pendente'' AND (qty IS DISTINCT FROM o.quantity OR val IS DISTINCT FROM o.estimated_value OR before_items IS DISTINCT FROM (SELECT coalesce(jsonb_agg(jsonb_build_object(''id'',id,''quantity'',quantity,''estimated_unit_value'',estimated_unit_value,''item_link'',item_link) ORDER BY id),''[]'') FROM public.purchase_order_items WHERE order_id=_order_id)) THEN RAISE EXCEPTION ''Após a compra, corrija somente os dados de entrega e retirada''; END IF;'||chr(10)||' after_data');
definition:=replace(definition,'SELECT coalesce(max(step_index),0)+1 INTO idx FROM public.approval_steps WHERE order_id=_order_id;', 'IF cfg.dual_approval_enabled AND val>cfg.dual_approval_threshold THEN IF cfg.dual_approval_job_title_1_id IS NULL OR cfg.dual_approval_job_title_2_id IS NULL OR cfg.dual_approval_job_title_1_id=cfg.dual_approval_job_title_2_id THEN RAISE EXCEPTION ''Configure os dois cargos de aprovação conjunta''; END IF; IF EXISTS(SELECT 1 FROM unnest(ARRAY[cfg.dual_approval_job_title_1_id,cfg.dual_approval_job_title_2_id]) title WHERE NOT public.has_job_title(o.requester_id,title) AND NOT EXISTS(SELECT 1 FROM public.profiles pr JOIN public.job_titles jt ON jt.id=title AND jt.active WHERE public.has_job_title(pr.id,title) AND pr.deleted_at IS NULL AND pr.id<>o.requester_id)) THEN RAISE EXCEPTION ''Um cargo de aprovação conjunta não tem aprovador ativo''; END IF; END IF; SELECT coalesce(max(step_index),0)+1 INTO idx FROM public.approval_steps WHERE order_id=_order_id;');
EXECUTE definition; END $$;